//! LocalDb / core-catalog parity harness (Todo 14, extended in Wave 2 Todo 4).
//!
//! Runs the real [`LocalDbDriver`] (default `--channel`) or [`CatalogService`]
//! (`--catalog`) against the seed database generated by
//! `scripts/qa/gen_parity_fixture.py` from `assets/app/db/apps.db`, then writes
//! the same JSON document the Dart harness produces from the real Floor DAO and
//! `LocalDbChannel`. Run through `scripts/qa/parity.sh`; the script rebuilds the
//! seed every run and is the gate.
//!
//! `--channel` opens the fixture directly (the driver applies the core schema
//! to its own copy). `--catalog` opens an already-imported core database and
//! answers every query through [`CatalogService`]. Both modes emit the same
//! document shape, so `parity_normalize.py` compares them unchanged.

use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

use serde_json::{json, Value};

use gstore_core::catalog::service::CatalogService;
use gstore_core::channel::{ChannelCategory, ChannelDriver, LocalDbDriver};
use gstore_core::db::DbHandle;
use gstore_core::dto::{
    AppDetail, AppSummary, ChannelKey, ChannelKind, ChannelMeta, DetailSection,
};
use gstore_core::error::Error;

const SEARCH_QUERY: &str = "clash";
const APP_ID: &str = "com.artemchep.keyguard";
const MISSING_APP_ID: &str = "com.example.missing";
const KNOWN_CATEGORY: &str = "PROXY";
const UNKNOWN_CATEGORY: &str = "NO_SUCH_CATEGORY";

struct Args {
    db: PathBuf,
    out: PathBuf,
    catalog: bool,
}

/// Query results shared by both harness modes.
struct Snapshot {
    all: Vec<AppSummary>,
    search: Vec<AppSummary>,
    search_empty: Vec<AppSummary>,
    by_category: Vec<AppSummary>,
    by_unknown_category: Vec<AppSummary>,
    info: Option<AppSummary>,
    info_missing: Option<AppSummary>,
    detail: Option<AppDetail>,
    detail_readme: Option<String>,
    detail_missing: Option<AppDetail>,
    detail_missing_readme: Option<String>,
    categories: Vec<ChannelCategory>,
}

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(err) => {
            eprintln!("gstore_core_parity: {err}");
            ExitCode::FAILURE
        }
    }
}

fn run() -> Result<(), String> {
    let args = parse_args()?;
    if !args.db.is_file() {
        return Err(format!("seed database not found: {}", args.db.display()));
    }

    let handle = DbHandle::open_at(&args.db)
        .map_err(|e| format!("open seeded db {}: {e}", args.db.display()))?;

    let snapshot = if args.catalog {
        collect_catalog(&handle)?
    } else {
        collect_driver(&handle)?
    };
    let document = document(&snapshot);

    if let Some(parent) = args.out.parent() {
        fs::create_dir_all(parent).map_err(|e| format!("create {}: {e}", parent.display()))?;
    }
    let bytes =
        serde_json::to_vec_pretty(&document).map_err(|e| format!("serialize parity json: {e}"))?;
    fs::write(&args.out, bytes).map_err(|e| format!("write {}: {e}", args.out.display()))?;
    Ok(())
}

fn collect_driver(handle: &DbHandle) -> Result<Snapshot, String> {
    let driver = LocalDbDriver::new(channel_key()?, channel_meta(), handle.clone());

    let all = driver
        .get_all_apps(false)
        .map_err(|e| format!("getAllApps: {e}"))?;
    let search = driver
        .search_apps(SEARCH_QUERY, false)
        .map_err(|e| format!("searchApps({SEARCH_QUERY}): {e}"))?;
    let search_empty = driver
        .search_apps("", false)
        .map_err(|e| format!("searchApps(\"\"): {e}"))?;
    let by_category = driver
        .search_by_category(KNOWN_CATEGORY, false)
        .map_err(|e| format!("searchByCategory({KNOWN_CATEGORY}): {e}"))?;
    let by_unknown_category = driver
        .search_by_category(UNKNOWN_CATEGORY, false)
        .map_err(|e| format!("searchByCategory({UNKNOWN_CATEGORY}): {e}"))?;

    let info = optional(driver.get_app_info(APP_ID, false))
        .map_err(|e| format!("getAppInfo({APP_ID}): {e}"))?;
    let info_missing = optional(driver.get_app_info(MISSING_APP_ID, false))
        .map_err(|e| format!("getAppInfo({MISSING_APP_ID}): {e}"))?;

    let detail = optional(driver.get_app_detail(APP_ID, false))
        .map_err(|e| format!("getAppDetail({APP_ID}): {e}"))?;
    let detail_readme = match &detail {
        Some(detail) => driver.fetch_readme(&detail.app_id).ok().flatten(),
        None => None,
    };
    let detail_missing = optional(driver.get_app_detail(MISSING_APP_ID, false))
        .map_err(|e| format!("getAppDetail({MISSING_APP_ID}): {e}"))?;

    let categories = channel_categories(handle, &driver)?;

    Ok(Snapshot {
        all,
        search,
        search_empty,
        by_category,
        by_unknown_category,
        info,
        info_missing,
        detail,
        detail_readme,
        detail_missing,
        detail_missing_readme: None,
        categories,
    })
}

/// Floor stores categories in `category`; the migrated core catalog uses
/// `categories`. `--channel` runs against the Floor fixture, so fall back to the
/// Floor table when the core table created by `DbHandle::open_at` is empty.
fn channel_categories(
    handle: &DbHandle,
    driver: &LocalDbDriver,
) -> Result<Vec<ChannelCategory>, String> {
    let categories = driver
        .get_all_categories(false)
        .map_err(|e| format!("getAllCategories: {e}"))?;
    if !categories.is_empty() {
        return Ok(categories);
    }
    handle
        .with_reader(|conn| {
            let mut statement = conn
                .prepare("SELECT id, description, icon FROM category ORDER BY rowid")
                .map_err(|error| gstore_core::db::DbError(error.to_string()))?;
            let rows = statement
                .query_map([], |row| {
                    Ok(ChannelCategory {
                        id: row.get(0)?,
                        description: row.get(1)?,
                        icon: row.get(2)?,
                    })
                })
                .map_err(|error| gstore_core::db::DbError(error.to_string()))?;
            rows.collect::<rusqlite::Result<Vec<_>>>()
                .map_err(|error| gstore_core::db::DbError(error.to_string()))
        })
        .map_err(|e| format!("getAllCategories: {e}"))
}

fn collect_catalog(handle: &DbHandle) -> Result<Snapshot, String> {
    let service =
        CatalogService::new(handle.clone()).map_err(|e| format!("catalog service: {e}"))?;

    let all = service.list().map_err(|e| format!("list: {e}"))?;
    let search = service
        .search(SEARCH_QUERY)
        .map_err(|e| format!("search({SEARCH_QUERY}): {e}"))?;
    let search_empty = service
        .search("")
        .map_err(|e| format!("search(\"\"): {e}"))?;
    let by_category = service
        .by_category(KNOWN_CATEGORY)
        .map_err(|e| format!("byCategory({KNOWN_CATEGORY}): {e}"))?;
    let by_unknown_category = service
        .by_category(UNKNOWN_CATEGORY)
        .map_err(|e| format!("byCategory({UNKNOWN_CATEGORY}): {e}"))?;

    let info = service
        .get_app(APP_ID)
        .map_err(|e| format!("getApp({APP_ID}): {e}"))?;
    let info_missing = service
        .get_app(MISSING_APP_ID)
        .map_err(|e| format!("getApp({MISSING_APP_ID}): {e}"))?;

    let detail = service
        .get_app_detail(APP_ID)
        .map_err(|e| format!("getAppDetail({APP_ID}): {e}"))?;
    let detail_readme = match &detail {
        Some(detail) => catalog_detail_readme(info.as_ref(), detail),
        None => None,
    };
    let detail_missing = service
        .get_app_detail(MISSING_APP_ID)
        .map_err(|e| format!("getAppDetail({MISSING_APP_ID}): {e}"))?;

    let categories = service
        .categories()
        .map_err(|e| format!("categories: {e}"))?;

    Ok(Snapshot {
        all,
        search,
        search_empty,
        by_category,
        by_unknown_category,
        info,
        info_missing,
        detail,
        detail_readme,
        detail_missing,
        detail_missing_readme: None,
        categories,
    })
}

/// Driver `fetch_readme` fallback: README column, else the description.
fn catalog_detail_readme(app: Option<&AppSummary>, detail: &AppDetail) -> Option<String> {
    let column = app
        .and_then(|app| app.readme.as_ref())
        .filter(|value| !value.is_empty())
        .cloned();
    column.or_else(|| (!detail.description.is_empty()).then(|| detail.description.clone()))
}

fn optional<T>(result: Result<T, Error>) -> Result<Option<T>, Error> {
    match result {
        Ok(value) => Ok(Some(value)),
        Err(Error::NotFound(_)) => Ok(None),
        Err(error) => Err(error),
    }
}

fn document(snapshot: &Snapshot) -> Value {
    json!({
        "queries": {
            "search": SEARCH_QUERY,
            "appId": APP_ID,
            "missingAppId": MISSING_APP_ID,
            "knownCategory": KNOWN_CATEGORY,
            "unknownCategory": UNKNOWN_CATEGORY,
        },
        "getAllApps": snapshot.all.iter().map(summary_json).collect::<Vec<_>>(),
        "searchApps": snapshot.search.iter().map(summary_json).collect::<Vec<_>>(),
        "searchEmpty": snapshot.search_empty.iter().map(summary_json).collect::<Vec<_>>(),
        "searchByCategory": {
            KNOWN_CATEGORY: snapshot.by_category.iter().map(summary_json).collect::<Vec<_>>(),
            UNKNOWN_CATEGORY: snapshot.by_unknown_category.iter().map(summary_json).collect::<Vec<_>>(),
        },
        "getAllCategories": snapshot.categories.iter().map(category_json).collect::<Vec<_>>(),
        "getAppInfo": snapshot.info.as_ref().map(summary_json),
        "getAppInfoMissing": snapshot.info_missing.as_ref().map(summary_json),
        "getAppDetail": snapshot.detail.as_ref().map(|detail| app_detail_json(detail, snapshot.detail_readme.clone())),
        "getAppDetailMissing": snapshot.detail_missing.as_ref().map(|detail| app_detail_json(detail, snapshot.detail_missing_readme.clone())),
    })
}

fn channel_key() -> Result<ChannelKey, String> {
    ChannelKey::new("local_db").map_err(|e| format!("invalid parity channel key local_db: {e}"))
}

fn channel_meta() -> ChannelMeta {
    ChannelMeta {
        kind: ChannelKind::LocalDb,
        name: "LocalDB".to_string(),
        description: "LocalDb parity channel".to_string(),
        enabled: true,
        priority: 10,
        support_offline: true,
        last_update_time: None,
        version: Some("1".to_string()),
    }
}

fn summary_json(app: &AppSummary) -> Value {
    json!({
        "appId": app.app_id,
        "packageName": app.package_name,
        "name": app.name,
        "user": app.user,
        "repositories": app.repositories,
        "icon": app.icon,
        "des": app.des,
        "readme": app.readme,
        "category": app.category,
        "extra": app.extra,
    })
}

fn category_json(category: &ChannelCategory) -> Value {
    json!({
        "id": category.id,
        "description": category.description,
        "icon": category.icon,
    })
}

/// Shared detail projection with the Dart harness.
///
/// Dart's `LocalDbChannelDetailProxy.extra` is a UI render payload (proxy,
/// repository name, apiData) with no corresponding SQLite column; both harnesses
/// compare the fields that come from the database plus the same readme/section
/// fallback (`fetchReadme` returns the README column, else `des`).
fn app_detail_json(detail: &AppDetail, readme: Option<String>) -> Value {
    json!({
        "appId": detail.app_id,
        "name": detail.name,
        "icon": detail.icon,
        "description": detail.description,
        "version": detail.version,
        "developer": detail.developer,
        "packageName": detail.package_name,
        "projectUrl": detail.project_url,
        "sections": detail.sections.iter().map(section_code).collect::<Vec<_>>(),
        "downloads": detail.downloads,
        "readme": readme,
    })
}

fn section_code(section: &DetailSection) -> &'static str {
    match section {
        DetailSection::Version => "version",
        DetailSection::Statistics => "statistics",
        DetailSection::Screenshots => "screenshots",
        DetailSection::Readme => "readme",
        DetailSection::Downloads => "downloads",
        DetailSection::Rating => "rating",
        DetailSection::Developer => "developer",
        DetailSection::Changelog => "changelog",
        DetailSection::Permissions => "permissions",
    }
}

fn parse_args() -> Result<Args, String> {
    let mut db = None;
    let mut out = None;
    let mut catalog = false;
    let mut iter = env::args().skip(1);
    while let Some(arg) = iter.next() {
        match arg.as_str() {
            "--db" => db = Some(iter.next().ok_or("--db requires a path")?),
            "--out" => out = Some(iter.next().ok_or("--out requires a path")?),
            "--catalog" => catalog = true,
            "--help" | "-h" => {
                return Err(
                    "usage: gstore_core_parity [--catalog] --db <path> --out <path>".to_string(),
                )
            }
            other => return Err(format!("unknown argument: {other}")),
        }
    }
    Ok(Args {
        db: Path::new(&db.ok_or("missing --db <path>")?).to_path_buf(),
        out: Path::new(&out.ok_or("missing --out <path>")?).to_path_buf(),
        catalog,
    })
}
